frappe.ui.form.on('Time and Daily Allowance', {
    validate: function(frm) {
        if (frm.doc.start_date && frm.doc.end_date) {
            // Condition 1: Start Date cannot be after End Date
            if (frm.doc.start_date > frm.doc.end_date) {
                frappe.throw('Start Date cannot be after End Date');
            }

            // Condition 2: End Date should not be more than 7 days from Start Date
            let start_date = new Date(frm.doc.start_date);
            let end_date = new Date(frm.doc.end_date);
            let difference_in_days = (end_date - start_date) / (1000 * 60 * 60 * 24); // Convert milliseconds to days

            if (difference_in_days > 7) {
                frappe.throw('End Date should not be more than 7 days after Start Date');
            }
        }
    }
});

frappe.ui.form.on('Project Attendance', {
    saving_in_progress: false, // ✅ Prevents infinite loop during save

    work_team: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent execution during save

        if (frm.doc.work_team) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Work Team",
                    name: frm.doc.work_team
                },
                callback: function (response) {
                    if (response.message && response.message.team_members_list) {
                        let work_team = response.message;

                        if (frm.doc.start_date && frm.doc.end_date) {
                            let start_date = new Date(frm.doc.start_date);
                            let end_date = new Date(frm.doc.end_date);

                            if (frm.fields_dict["attendance_to_be_marked"]) {
                                frm.clear_table("attendance_to_be_marked");

                                let marked_combinations = new Set();
                                if (frm.doc.attendance_marked) {
                                    frm.doc.attendance_marked.forEach(row => {
                                        let row_date = new Date(row.date);
                                        if (row_date >= start_date && row_date <= end_date) {
                                            marked_combinations.add(`${row.employee_id}-${row.date}`);
                                        }
                                    });
                                }

                                for (let d = new Date(start_date); d <= end_date; d.setDate(d.getDate() + 1)) {
                                    let currentDate = new Date(d);
                                    let formatted_date = frappe.datetime.obj_to_str(currentDate);

                                    work_team.team_members_list.forEach(member => {
                                        let combination = `${member.employee_id}-${formatted_date}`;

                                        if (!marked_combinations.has(combination)) {
                                            let exists = frm.doc.attendance_to_be_marked.some(row =>
                                                row.employee_id === member.employee_id && row.date === formatted_date
                                            );

                                            if (!exists) {
                                                let row = frm.add_child("attendance_to_be_marked");
                                                row.employee_id = member.employee_id;
                                                row.full_name = member.full_name;
                                                row.date = formatted_date;
                                                row.present = "";
                                                row.allowance = "";
                                                row.duration = 8;
                                            }
                                        }
                                    });
                                }
                                frm.refresh_field("attendance_to_be_marked");
                            }
                        }

                        if (frm.fields_dict["team_members"]) {
                            frm.clear_table("team_members");

                            work_team.team_members_list.forEach(member => {
                                let row = frm.add_child("team_members");
                                row.employee_id = member.employee_id;
                                row.full_name = member.full_name;
                                row.email = member.email;
                            });
                            frm.refresh_field("team_members");
                        }
                    }
                }
            });
        }
    },

    start_date: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent execution during save
        frm.trigger('refresh_attendance_marked');
        frm.trigger('work_team');
    },

    end_date: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent execution during save
        frm.trigger('refresh_attendance_marked');
        frm.trigger('work_team');
    },

    project__client: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent execution during save
        frm.trigger('refresh_attendance_marked');
    },

    refresh_attendance_marked: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent execution during save

        if (frm.doc.project__client && frm.doc.start_date && frm.doc.end_date) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Employee Attendance Master",
                    filters: {
                        project: frm.doc.project__client,
                        date: ["between", [frm.doc.start_date, frm.doc.end_date]]
                    },
                    fields: ["employee", "full_name", "date", "duration", "present", "allowance", "project"]
                },
                callback: function (response) {
                    if (response.message && frm.fields_dict["attendance_marked"]) {
                        let marked_attendances = response.message;
                        frm.clear_table("attendance_marked");

                        marked_attendances.forEach(attendance => {
                            let row = frm.add_child("attendance_marked");
                            row.employee_id = attendance.employee;
                            row.full_name = attendance.full_name;
                            row.date = attendance.date;
                            row.duration = attendance.duration;
                            row.present = attendance.present;
                            row.allowance = attendance.allowance;
                            row.project = attendance.project;
                        });

                        frm.refresh_field("attendance_marked");
                        frm.trigger('work_team');
                    }
                }
            });
        }
    },

    before_save: function (frm) {
        frm.saving_in_progress = true; // ✅ Disable triggers during save
    },

    after_save: function (frm) {
        setTimeout(() => {
            frm.saving_in_progress = false; // ✅ Enable triggers after save
        }, 500);
    },

    save: function (frm) {
        if (frm.saving_in_progress) return; // ✅ Prevent infinite save loop
        frm.saving_in_progress = true;

        frm.refresh_field("attendance_to_be_marked");
        frm.refresh_field("attendance_marked");

        if (!frm.is_dirty()) {
            frappe.msgprint(__("No changes to save."));
            frm.saving_in_progress = false;
            return;
        }

        frm.save().then(() => {
            frm.saving_in_progress = false; // ✅ Reset flag after successful save
        }).catch(() => {
            frappe.msgprint(__("Error saving document. Please try again."));
            frm.saving_in_progress = false;
        });
    },

    attendance_to_be_marked_custom_present: function (frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (row.present === "Yes" || row.present === "No") {
            frappe.call({
                method: "frappe.client.insert",
                args: {
                    doc: {
                        doctype: "Employee Attendance Master",
                        employee: row.employee_id,
                        full_name: row.full_name,
                        date: row.date,
                        duration: row.duration,
                        present: row.present,
                        allowance: row.allowance,
                        project: frm.doc.project__client
                    }
                },
                callback: function(response) {
                    if (response.message && frm.fields_dict["attendance_marked"]) {
                        let existing_entry = frm.doc.attendance_marked.some(r =>
                            r.employee_id === row.employee_id && r.date === row.date
                        );

                        if (!existing_entry) {
                            let marked_row = frm.add_child("attendance_marked");
                            marked_row.employee_id = row.employee_id;
                            marked_row.full_name = row.full_name;
                            marked_row.date = row.date;
                            marked_row.duration = row.duration;
                            marked_row.present = row.present;
                            marked_row.allowance = row.allowance;
                            marked_row.project = frm.doc.project__client;
                        }

                        frm.remove_from_child_table("attendance_to_be_marked", row.name);
                        frm.refresh_field("attendance_to_be_marked");
                        frm.refresh_field("attendance_marked");
                    }
                }
            });
        }
    }
});

