frappe.ui.form.on("Project Attendance", {

    on_submit: function (frm) {
        let doc = frm.doc;

        // Process each row in the attendance_to_be_marked table
        (doc.attendance_to_be_marked || []).forEach(row => {
            if (["Yes", "No"].includes(row.present)) {
                // Directly insert a new entry without checking for existing ones
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Employee Attendance Master",
                            employee: row.employee_id,
                            full_name: row.full_name,
                            date: row.date,
                            duration: row.duration,
                            present: row.present,
                            allowance: row.allowance,
                            project: doc.project__client
                            // object: doc.object
                        }
                    },
                    callback: function (insert_res) {
                        if (!insert_res.exc) {
                            frappe.msgprint(`✅ Attendance Marked for: ${row.employee_id}`);
                        } else {
                            frappe.msgprint("An error occurred while creating the entry.");
                        }
                    }
                });
            }
        });
    }
});

