frappe.ui.form.on('Project Attendance', {
    refresh(frm) {
        hideTableButtons(frm, 'attendance_to_be_marked');
        hideTableButtons(frm, 'attendance_marked');
    },
    start_date(frm) {
        hideTableButtons(frm, 'attendance_to_be_marked');
        hideTableButtons(frm, 'attendance_marked');
    },
    end_date(frm) {
        hideTableButtons(frm, 'attendance_to_be_marked');
        hideTableButtons(frm, 'attendance_marked');
    }
});

function hideTableButtons(frm, table_name) {
    if (frm.fields_dict[table_name] && frm.fields_dict[table_name].grid && frm.fields_dict[table_name].grid.wrapper) {
        const wrapper = frm.fields_dict[table_name].grid.wrapper;
        wrapper.find('.grid-add-row').hide(); // Hides "Add Row"
        wrapper.find('.grid-footer').hide(); // Hides entire footer with add-row & controls
    }
}

